import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

mse_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mse_kernel(const float* pred, const float* targ, float* sum_val, int size) {
    __shared__ float sdata[256];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;
    float diff = 0.0f;
    if (i < size) {
        float temp = pred[i] - targ[i];
        diff = temp * temp;
    }
    sdata[tid] = diff;
    __syncthreads();

    // Parallel reduction within the block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Atomic add the block's result to the global sum
    if (tid == 0) {
        atomicAdd(sum_val, sdata[0]);
    }
}

torch::Tensor mse_cuda_forward(torch::Tensor pred, torch::Tensor targ) {
    int size = pred.numel();
    auto sum_val = torch::zeros({1}, pred.options());
    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    mse_kernel<<<grid_size, block_size>>>(pred.data_ptr<float>(),
                                          targ.data_ptr<float>(),
                                          sum_val.data_ptr<float>(),
                                          size);
    cudaDeviceSynchronize();

    // Divide by total number of elements for mean
    auto out = sum_val / size;
    return out;
}
"""

mse_cpp_src = "torch::Tensor mse_cuda_forward(torch::Tensor pred, torch::Tensor targ);"

# Build the custom module
mse_module = load_inline(
    name="mse_module",
    cpp_sources=mse_cpp_src,
    cuda_sources=mse_source,
    functions=["mse_cuda_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.mse = mse_module

    def forward(self, predictions, targets):
        return self.mse.mse_cuda_forward(predictions, targets)
